insert into public.foods (slug, status, hidden, sort_order, name, change_label, why, summary, category, tags, cook_minutes, cook_label, difficulty, servings, likes, videos, multiplier, trend, image, alt, hero_image, hero_alt, steps, tip, convenience) values ('dubai-chocolate', 'published', false, 10, '두바이 초콜릿', '오늘 급상승 1위', '피스타치오 크림과 바삭한 카다이프를 채운 초콜릿. 일주일 새 검색량이 세 배로 늘었어요.', '초콜릿 안에 피스타치오 크림과 바삭하게 볶은 카다이프 면을 채운 디저트예요. 해외에서 먼저 유행했고, 이번 주 국내에서 집에서 만드는 영상이 48개 올라오며 검색량이 지난주의 3.2배가 됐어요. 편의점에도 비슷한 제품이 나오기 시작했어요.', '디저트', array['디저트']::text[], 40, '조리 40분, 굳히기 1시간', '보통', '8조각 분량', 1240, 48, 3.2, array[12, 13, 12, 15, 14, 18, 20, 24, 31, 40, 47, 56, 65, 76]::integer[], 'dubai', '접시에 놓인 두바이 초콜릿 조각, 단면에 초록 피스타치오 속이 보인다', 'dubai2', '초록 포장지 위에 놓인 한입 베어 문 두바이 초콜릿, 피스타치오 속이 보인다', '[{"text":"카다이프 면을 2cm 길이로 자르고, 버터를 녹인 팬에서 약불로 노릇해질 때까지 볶아요.","timerMinutes":8},{"text":"볶은 카다이프를 한 김 식힌 뒤 피스타치오 스프레드, 소금 한 꼬집과 섞어요."},{"text":"다크 초콜릿을 중탕으로 녹여 틀 안쪽에 얇게 바르고 냉동실에서 굳혀요.","timerMinutes":10},{"text":"2번 필링을 꾹꾹 눌러 채우고, 남은 초콜릿으로 윗면을 덮어요."},{"text":"냉장실에서 1시간 굳힌 뒤 틀에서 꺼내 잘라요.","timerMinutes":60}]'::jsonb, '카다이프를 덜 볶으면 금방 눅눅해져요. 갈색이 돌고 바스락 소리가 날 때까지 볶아 주세요.', '[{"place":"편의점 디저트 코너","desc":"''두바이 스타일'' 초콜릿 바, 쿠키 제품이 나와 있어요"},{"place":"대형마트 수입과자 코너","desc":"피스타치오 크림 초콜릿을 찾아보세요"}]'::jsonb)
