insert into public.foods (slug, status, hidden, sort_order, name, change_label, why, summary, category, tags, cook_minutes, cook_label, difficulty, servings, likes, videos, multiplier, trend, image, alt, hero_image, hero_alt, steps, tip, convenience) values ('chicken-mayo-deopbap', 'published', false, 20, '치킨마요 덮밥', '어제보다 2계단 올라왔어요', '남은 치킨을 잘게 찢어 마요네즈, 데리야끼 소스와 함께 밥 위에. 배달 치킨 다음 날 메뉴로 많이 찾아요.', '배달 치킨이 남았을 때 만드는 덮밥이에요. 주말 다음 날 검색이 몰리는 패턴이 이번 주 더 커졌고, ''남은 치킨 활용'' 영상이 31개 올라왔어요.', '밥', array['10분컷', '자취생']::text[], 10, '조리 10분', '쉬움', '1인분', 8410, 31, 2.1, array[10, 12, 15, 12, 15, 19, 17, 22, 27, 27, 33, 40, 42, 50]::integer[], 'deopbap', '치킨 위에 마요네즈와 채소를 올린 덮밥', null, null, '[{"text":"남은 치킨은 살만 발라 잘게 찢고, 팬에 데리야끼 소스 2큰술과 함께 1분 볶아요.","timerMinutes":1},{"text":"계란 1개를 스크램블로 부드럽게 익혀요."},{"text":"밥 위에 계란, 치킨 순으로 올리고 마요네즈와 김 플레이크를 뿌려요."}]'::jsonb, '치킨 껍질은 따로 바삭하게 구워 올리면 식감이 살아나요.', '[{"place":"편의점 도시락 코너","desc":"치킨마요 덮밥 도시락이 대부분 매장에 있어요"}]'::jsonb)
