insert into public.foods (slug, status, hidden, sort_order, name, change_label, why, summary, category, tags, cook_minutes, cook_label, difficulty, servings, likes, videos, multiplier, trend, image, alt, hero_image, hero_alt, steps, tip, convenience) values ('shrimp-rose-tteokbokki', 'published', false, 30, '새우 로제 떡볶이', '1계단 올라왔어요', '고추장 소스에 우유와 크림치즈를 더해 덜 맵고 고소하게. 분식집 인기 메뉴를 집에서.', '프랜차이즈 신메뉴 출시 뒤 ''집에서 로제 떡볶이'' 검색이 늘었어요. 이번 주 관련 영상 27개.', '분식', array['안주']::text[], 20, '조리 20분', '쉬움', '2인분', 6920, 27, 1.8, array[10, 12, 15, 11, 14, 18, 16, 20, 25, 24, 29, 35, 36, 43]::integer[], 'tteokbokki', '새우와 떡이 들어간 주황빛 로제 떡볶이', null, null, '[{"text":"떡은 물에 10분 불리고, 새우는 찬물에 해동해요.","timerMinutes":10},{"text":"팬에 우유 300ml, 고추장 2큰술, 크림치즈 2큰술을 넣고 저어 가며 끓여요."},{"text":"떡과 새우를 넣고 중불에서 7분 졸인 뒤 치즈 1장을 올려 녹여요.","timerMinutes":7}]'::jsonb, '우유가 끓어 넘치기 쉬우니 중약불을 유지하세요.', '[{"place":"편의점 즉석식품 코너","desc":"컵 로제 떡볶이가 나와 있어요"}]'::jsonb)
