insert into public.foods (slug, status, hidden, sort_order, name, change_label, why, summary, category, tags, cook_minutes, cook_label, difficulty, servings, likes, videos, multiplier, trend, image, alt, hero_image, hero_alt, steps, tip, convenience) values ('airfryer-gyeranppang', 'published', false, 40, '에어프라이어 계란빵', '순위 그대로', '핫케이크 가루 반죽에 계란을 하나씩. 에어프라이어 15분이면 길거리 그 맛이에요.', '날씨가 추워지며 길거리 간식 검색이 함께 늘었어요. 에어프라이어 버전 영상이 22개.', '간식', array['10분컷', '자취생']::text[], 15, '조리 15분', '쉬움', '4개', 5130, 22, 1.5, array[10, 12, 14, 11, 14, 17, 14, 18, 22, 20, 25, 30, 29, 35]::integer[], 'gyeranppang', '철판 위에 줄지어 구워지는 계란빵', null, null, '[{"text":"핫케이크 가루 200g, 우유 150ml, 계란 1개를 섞어 반죽해요."},{"text":"머핀컵에 반죽을 절반 채우고 햄 조각과 계란 1개를 올려요."},{"text":"170도 에어프라이어에서 15분 구워요.","timerMinutes":15}]'::jsonb, '노른자에 이쑤시개로 구멍을 한 번 내면 터지지 않아요.', '[{"place":"편의점 베이커리 코너","desc":"계란빵·계란 머핀 제품을 찾아보세요"}]'::jsonb)
