insert into public.foods (slug, status, hidden, sort_order, name, change_label, why, summary, category, tags, cook_minutes, cook_label, difficulty, servings, likes, videos, multiplier, trend, image, alt, hero_image, hero_alt, steps, tip, convenience) values ('shrimp-cream-risotto', 'published', false, 50, '새우 크림 리조또', '1계단 내려갔어요', '즉석밥에 우유와 치즈를 넣고 졸이면 끝. 냉동 새우로 충분해요.', '''즉석밥 리조또'' 영상이 꾸준히 올라오고 있어요. 이번 주 19개.', '밥', array['자취생']::text[], 25, '조리 25분', '보통', '1인분', 4870, 19, 1.3, array[10, 12, 14, 11, 13, 16, 13, 17, 20, 18, 22, 26, 25, 30]::integer[], 'risotto', '새우와 채소를 올린 크림 리조또', null, null, '[{"text":"버터를 녹인 팬에 새우와 버섯을 넣고 3분 볶아요.","timerMinutes":3},{"text":"즉석밥과 우유 200ml를 넣고 저어 가며 8분 졸여요.","timerMinutes":8},{"text":"불을 끄고 치즈 가루 2큰술을 넣어 섞어요."}]'::jsonb, '우유를 한 번에 다 넣지 말고 두 번에 나눠 넣으면 덜 뭉쳐요.', '[{"place":"편의점 냉동식품 코너","desc":"냉동 크림 리조또를 데워 맛볼 수 있어요"}]'::jsonb)
