insert into public.foods (slug, status, hidden, sort_order, name, change_label, why, summary, category, tags, cook_minutes, cook_label, difficulty, servings, likes, videos, multiplier, trend, image, alt, hero_image, hero_alt, steps, tip, convenience) values ('tuna-gimbap', 'published', false, 60, '참치 김밥', '2계단 내려갔어요', '깻잎으로 참치마요를 감싸 말면 물기 없이 깔끔해요.', '소풍철이 지나며 조금 내려왔지만 ''깻잎 참치김밥'' 검색은 여전히 높아요.', '밥', array['자취생']::text[], 20, '조리 20분', '보통', '3줄', 3960, 15, 1.1, array[10, 12, 14, 10, 13, 15, 12, 15, 18, 15, 19, 22, 20, 24]::integer[], 'gimbap', '접시에 썰어 놓은 김밥', null, null, '[{"text":"참치는 기름을 꼭 짜고 마요네즈 2큰술과 섞어요."},{"text":"김 위에 밥을 얇게 펴고 깻잎 2장, 참치마요, 단무지·우엉을 올려요."},{"text":"단단히 말아 참기름을 바르고 잘라요."}]'::jsonb, '칼에 물을 묻혀 가며 썰면 단면이 깔끔해요.', '[{"place":"편의점 김밥 코너","desc":"참치마요 삼각김밥·김밥이 늘 있어요"}]'::jsonb)
