insert into public.foods (slug, status, hidden, sort_order, name, change_label, why, summary, category, tags, cook_minutes, cook_label, difficulty, servings, likes, videos, multiplier, trend, image, alt, hero_image, hero_alt, steps, tip, convenience) values ('butter-garaetteok', 'published', false, 70, '버터 가래떡구이', '새로 들어왔어요', '가래떡을 버터에 노릇하게 굽고 꿀을 한 줄. 겨울 간식으로 다시 뜨고 있어요.', '카페 신메뉴로 소개된 뒤 검색이 이번 주 새로 올라왔어요. 영상 12개.', '간식', array['10분컷', '디저트']::text[], 10, '조리 10분', '쉬움', '2인분', 3720, 12, 2.4, array[10, 12, 14, 11, 14, 17, 15, 19, 23, 22, 27, 32, 32, 38]::integer[], 'garaetteok', '접시에 가지런히 놓인 가래떡', null, null, '[{"text":"굳은 가래떡은 끓는 물에 1분 데쳐 말랑하게 해요.","timerMinutes":1},{"text":"버터를 녹인 팬에서 앞뒤로 노릇하게 5분 구워요.","timerMinutes":5},{"text":"꿀을 한 줄 뿌려 바로 먹어요."}]'::jsonb, '소금을 아주 조금 뿌리면 단맛이 더 살아나요.', '[{"place":"떡집·마트 떡 코너","desc":"말랑한 가래떡을 사면 데치지 않아도 돼요"}]'::jsonb)
